function contentDragonFire(monster,target){const from={x:monster.x+.5,y:monster.y+.3},to={x:target.x+.5,y:target.y+.4},homing=monster.tier===3,flame={from,to,target,homing,p:0};queue.push({dur:Math.min(650,220+dist(monster,target)*20),update(p){flame.p=p;if(!contentFlames.includes(flame))contentFlames.push(flame);if(homing){flame.to={x:target.rx+.5,y:target.ry+.4};}if(!flame.started){flame.started=true;sfx('fire');}},end(){contentFlames=contentFlames.filter(item=>item!==flame);}});fxStep(()=>{ring(target,'#ffaf45',1.3,350);sparks(target,'#ffc260',22,.09,.02);sfx('fire');},140);}
function drawContentFlames(sx,sy,now){for(const flame of contentFlames){const bend=flame.homing?Math.sin(flame.p*Math.PI)*1.3:0;for(let i=9;i>=0;i--){const p=Math.max(0,flame.p-i*.024),x=flame.from.x+(flame.to.x-flame.from.x)*p,y=flame.from.y+(flame.to.y-flame.from.y)*p-Math.sin(p*Math.PI)*bend;ctx.save();ctx.globalAlpha=(1-i/11)*.9;const radius=Math.max(3,17-i*1.25);ctx.fillStyle=i>4?'#d84b2b':'#ff9e39';ctx.beginPath();ctx.arc(sx(x),sy(y),radius,0,7);ctx.fill();if(i<4){ctx.fillStyle='#fff1ac';ctx.beginPath();ctx.arc(sx(x)-2,sy(y)-2,radius*.48,0,7);ctx.fill();}ctx.restore();}}}
function drawContentPoisonIcon(context,x,y){context.save();context.translate(x,y);context.fillStyle='#263226';context.strokeStyle='#b0d787';context.lineWidth=1;context.beginPath();context.arc(0,0,10,0,7);context.fill();context.stroke();context.fillStyle='#b8df8c';context.beginPath();context.moveTo(0,-6);context.quadraticCurveTo(8,2,0,6);context.quadraticCurveTo(-8,2,0,-6);context.fill();context.restore();}
